<template><view class="login"><view class="logo">柜</view><view class="title">实验室智能柜</view><view class="subtitle">设备借用 · 工位预约 · 实验室管理</view><view class="card"><view class="tabs"><text :class="{active:!register}" @tap="register=false">账号登录</text><text :class="{active:register}" @tap="register=true">注册账号</text></view><input v-model="phone" type="number" :maxlength="register ? 11 : 6" :placeholder="register ? '手机号' : '演示账号'"/><input v-model="password" password placeholder="密码（6位）" maxlength="64"/><view v-if="register" class="tip">新注册账号的人员类型为学生，先进入“我的借还”。</view><button class="submit" :loading="busy" :disabled="busy" @tap="submit">{{register?'注册并进入':'登录'}}</button><view v-if="!register" class="forgot" @tap="forgotPassword">忘记密码？</view><view v-if="error" class="error">{{error}}</view></view><view v-if="demo" class="demo"><view>本地演示模式 · 不连接真实微信或柜机</view><view>学生账号：000001</view><view>教师管理员：000002</view><view>教师审批人：000003</view><view>统一演示密码：123456</view></view></view></template>
<script>
import {login,destination,safeReLaunch} from '../../services/auth.js'
import {config} from '../../config.js'
export default{data:()=>({register:false,name:'',phone:'',password:'',busy:false,error:'',demo:config.mode==='demo'}),methods:{forgotPassword(){uni.navigateTo({url:'/pages/password/index?mode=reset'})},async submit(){if(this.busy)return;this.busy=true;this.error='';try{await login(this.phone.trim(),this.password,this.register,this.name.trim());safeReLaunch(destination())}catch(e){this.error=e.message}finally{this.busy=false}}}}
</script>
<style scoped>.login{padding:70rpx 40rpx}.logo{width:104rpx;height:104rpx;border-radius:28rpx;background:#4f46e5;color:white;font-size:56rpx;text-align:center;line-height:104rpx;margin:0 auto 28rpx}.title{text-align:center;font-size:42rpx;font-weight:700}.subtitle{text-align:center;color:#64748b;margin:18rpx 0 50rpx}.card{padding:34rpx;background:white;border:1px solid #e7eaf2;border-radius:26rpx}.tabs{display:flex;gap:40rpx;margin-bottom:30rpx;color:#64748b}.active{color:#4f46e5;font-weight:bold}.card input{height:94rpx;margin:20rpx 0;padding:20rpx;border:1px solid #dce1ea;border-radius:18rpx;font-size:28rpx}.submit{background:#4f46e5;color:white;margin-top:30rpx}.forgot{text-align:right;color:#4f46e5;font-size:25rpx;margin-top:20rpx}.tip,.demo{color:#64748b;font-size:24rpx;line-height:1.9}.demo{margin:32rpx 16rpx}.error{color:#dc2626;margin-top:20rpx}</style>
